package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Transfers a person of a sheet, with their claims, to another sheet. */
@Service
public class PersonTransferService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final StatementRepository statements;
    private final PoolMemberRepository poolMembers;
    private final SheetService sheets;
    private final SettingsService settings;
    private final RollupService rollup;
    private final Audit audit;

    public PersonTransferService(PersonRepository people, PatronRepository patrons, WatchRepository watches,
            ClaimRepository claims, ClaimService claimService, StatementRepository statements,
            PoolMemberRepository poolMembers, SheetService sheets, SettingsService settings, RollupService rollup,
            Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.claimService = claimService;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.sheets = sheets;
        this.settings = settings;
        this.rollup = rollup;
        this.audit = audit;
    }

    /**
     * A steward transfers the person to the other sheet. They arrive with every grade (and its from-date), their
     * holds, terms, contact and aliases, and their claims with status, dates, notes, tags, frozen figures and logs,
     * listed newest first as they were; each claim that had a number takes the other sheet's next, in the order the
     * claims were opened (by the sheet's today when each was opened, then the order they were added). Figures a
     * statement bound are lost, their statements dropped, and references are not carried. Their patron links, pool
     * memberships and watches are dropped, and they leave this sheet. Refused unless the user is a steward, for a
     * retired person, for this sheet's own id, for an archived sheet, and when their name, an alias or their contact
     * is already a name, alias or contact on the other sheet.
     */
    @Transactional
    public void transfer(String by, String sheetId, Long id, String toSheetId) {
        if (!settings.isSteward(sheetId, by)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can transfer people.");
        }
        if (sheetId.equals(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet.");
        }
        // both sheets are locked, in the order of their ids, so two transfers between them never deadlock
        if (sheetId.compareTo(toSheetId) < 0) {
            sheets.lock(sheetId);
            sheets.lock(toSheetId);
        } else {
            sheets.lock(toSheetId);
            sheets.lock(sheetId);
        }
        if (settings.isArchived(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet is archived.");
        }
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (person.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred.");
        }
        List<String> names = new ArrayList<>();
        names.add(person.getName());
        names.addAll(person.getAliases());
        if (names.stream().anyMatch(n -> people.nameOrAliasInUse(toSheetId, n))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The name or an alias is already on the other sheet.");
        }
        if (person.getContact() != null && people.existsBySheetIdAndContact(toSheetId, person.getContact())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The contact is already on the other sheet.");
        }
        RollupService.Snapshot beforeHere = rollup.snapshot(sheetId);
        RollupService.Snapshot beforeThere = rollup.snapshot(toSheetId);

        // what links the person to others on this sheet is dropped
        patrons.deleteAll(patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(p -> p.getPersonId().equals(id) || p.getPatronId().equals(id)).toList());
        List<PoolMember> memberships = poolMembers.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(m -> id.equals(m.getPersonId())).toList();
        poolMembers.deleteAll(memberships);
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(id));
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, id));
        patrons.flush();
        poolMembers.flush();
        watches.flush();
        statements.flush();

        person.moveToSheet(toSheetId);
        // they go to the end of the other sheet's list
        person.setPosition(people.nextPosition(toSheetId));
        people.saveAndFlush(person);

        List<Claim> moved = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, id));
        // numbered afresh in the order they were opened
        moved.sort(Comparator.comparing(Claim::openedOn, Comparator.nullsFirst(Comparator.naturalOrder()))
                .thenComparing(Claim::getId));
        Map<String, String> renumbered = new HashMap<>();
        for (Claim c : moved) {
            String was = c.getNumber();
            c.moveToSheet(toSheetId);
            claimService.takeIn(toSheetId, c);
            if (was != null) {
                renumbered.put(was, c.getNumber());
            }
        }
        // a claim naming another of theirs by number names it by its new one; one naming any other names none
        for (Claim c : moved) {
            if (c.getCorrects() != null) {
                c.setCorrects(renumbered.get(c.getCorrects()));
            }
            if (c.getSplitFrom() != null) {
                c.setSplitFrom(renumbered.get(c.getSplitFrom()));
            }
            claims.saveAndFlush(c);
        }
        // listed as the other sheet's newest, in the order they were listed here
        moved.sort(Comparator.comparing(Claim::getListed, Comparator.nullsFirst(Comparator.naturalOrder()))
                .thenComparing(Claim::getId));
        for (Claim c : moved) {
            claims.relist(c.getId());
        }

        String name = person.getName();
        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + by + " name=" + name + " to="
                + toSheetId);
        rollup.recordChanges(by, sheetId, beforeHere);
        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + toSheetId + " by=" + by + " name=" + name + " from="
                + sheetId);
        rollup.recordChanges(by, toSheetId, beforeThere);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.asof.AsOfContext;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 *
 * A record of a change made by a user acting on behalf of another (see {@link OnBehalf}) ends with for=<that one>,
 * unless it only reports figures (ROLLUP, TOTALS, ALERT). A SNAPSHOT, written by a change of today the user makes,
 * carries it too.
 */
@Service
public class Audit {

    /** Tells for whom a user acts on a sheet, when they act on another's behalf. */
    public interface OnBehalf {
        Optional<String> forOf(String sheetId, String user);
    }

    /** The records that only report figures, which never carry for=. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    /** A record's event, sheet and user: its head. */
    private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(\\S+) by=(.+?)(?= [a-z][a-z-]*=|$)");

    private final Path file;
    private final ObjectProvider<OnBehalf> onBehalf;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<OnBehalf> onBehalf) {
        this.file = Path.of(path);
        this.onBehalf = onBehalf;
    }

    /**
     * Append one audit record. Tests assert the exact line(s) in the file. A request answered as of a date changes
     * nothing, so it writes none.
     */
    public synchronized void record(String entry) {
        if (AsOfContext.active()) {
            return;
        }
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused (and
     * rolled back) writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String record) {
        String entry = record + onBehalfOf(record);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** " for=<who>" when the record's user makes the change on another's behalf, as things stand now; else "". */
    private String onBehalfOf(String entry) {
        Matcher m = HEAD.matcher(entry);
        OnBehalf who = onBehalf.getIfAvailable();
        if (who == null || !m.find() || FIGURES_ONLY.contains(m.group(1))) {
            return "";
        }
        return who.forOf(m.group(2), m.group(3)).map(f -> " for=" + f).orElse("");
    }

    /** A field of a record: its key and value, the value running to the next field or the end. */
    private static final Pattern FIELD = Pattern.compile("(?<=^| )([a-z][a-z-]*)=(.*?)(?= [a-z][a-z-]*=|$)");

    /**
     * The records of a sheet exactly as the file holds them, newest first. With a name, only those about that person:
     * carrying name= or person= that name, compared as names are (case and surrounding spaces ignored).
     */
    public synchronized List<String> lines(String sheetId, String name) {
        if (!Files.exists(file)) {
            return List.of();
        }
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        String key = name == null ? "" : name.strip().toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        for (String line : all) {
            Matcher m = HEAD.matcher(line);
            if (m.find() && m.group(2).equals(sheetId) && (key.isEmpty() || about(line, key))) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    /** Whether a record carries name= or person= the given name key. */
    private static boolean about(String line, String key) {
        Matcher f = FIELD.matcher(line);
        while (f.find()) {
            String k = f.group(1);
            if ((k.equals("name") || k.equals("person")) && f.group(2).strip().toLowerCase(Locale.ROOT).equals(key)) {
                return true;
            }
        }
        return false;
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit viewer: the active sheet's audit lines exactly as the file holds them, newest first. With a name in the
// filter, only the lines about that person (name= or person= that name, case and surrounding spaces ignored).
@Component({
  selector: 'app-audit-viewer',
  template: `
    <section aria-label="Audit">
      <h2>Audit</h2>
      <form (submit)="show($event)" aria-label="Show the audit">
        <label for="audit-filter">Person</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filter()"
          (input)="filter.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="audit-show">Show audit</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err }}</p>
        }
      </form>

      <ol aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditViewer {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly lines = signal<readonly string[]>([]);
  protected readonly filter = signal('');
  protected readonly error = signal<string | null>(null);
  // Each press is numbered, so only the latest one's answer shows.
  private press = 0;

  constructor() {
    // A newly loaded sheet starts with the list empty.
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.press++;
        this.error.set(null);
        this.lines.set([]);
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async show(e: Event): Promise<void> {
    e.preventDefault();
    this.error.set(null);
    this.lines.set([]);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const press = ++this.press;
    try {
      const l = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, {
          params: { name: this.filter() },
        }),
      );
      if (press === this.press) this.lines.set(l);
    } catch {
      if (press === this.press) this.error.set('Could not read the audit.');
    }
  }
}
