    private Integer terms;

    /** The person's contact, without surrounding spaces and lower-cased; null: none. */
    @Column(name = "contact")
    private String contact;

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The sheet's today when the person was added; null: before that was kept. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** The sheet's today when the retirement date was set; null: before that was kept, or not retired. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedHold> holds = new ArrayList<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonAlias> aliases = new ArrayList<>();

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this(sheetId, name, grade, null);
    }

    /** A person added while the sheet's today was the date. */
    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.name = name;
        this.addedOn = addedOn;
        this.grades.add(new DatedGrade(grade, null, addedOn));
    }

    /**
     * The person as they stood at the end of the day, for figures taken as of it: only the grades, holds and
     * retirement recorded while the sheet's today was on or before the day. Not to be saved.
     */
    public Person asOf(LocalDate day) {
        Person then = new Person();
        then.id = id;
        then.sheetId = sheetId;
        then.name = name;
        then.position = position;
        then.terms = terms;
        then.addedOn = addedOn;
        then.version = version;
        grades.stream().filter(g -> g.madeBy(day)).forEach(then.grades::add);
        if (then.grades.isEmpty()) {
            // the first grade they were given stands for them
            grades.stream().filter(g -> g.getFrom() == null).forEach(then.grades::add);
        }
        holds.stream().filter(h -> h.madeBy(day)).forEach(then.holds::add);
        then.aliases.addAll(aliases);
        if (retiredOn == null || !retiredOn.isAfter(day)) {
            then.retiredFrom = retiredFrom;
            then.retiredOn = retiredOn;
        }
        return then;
    }

    /** Whether the person had been added by the end of the day: added while the sheet's today was on or before it. */
    public boolean addedBy(LocalDate day) {
        return addedOn == null || !addedOn.isAfter(day);
    }

    }

    /** The person's aliases, sorted as names are compared: ignoring case. */
    public List<String> getAliases() {
        return aliases.stream().map(PersonAlias::getAlias)
                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(a -> a))
                .toList();
    }

    /** Moves the person, with their grades, holds and aliases, to the other sheet. */
    public void moveToSheet(String sheetId) {
        this.sheetId = sheetId;
        List<PersonAlias> moved = aliases.stream().map(a -> new PersonAlias(sheetId, a.getAlias())).toList();
        aliases.clear();
        aliases.addAll(moved);
    }

    /** Gives the person the alias, without surrounding spaces; the ones already given are kept. */
    public void addAlias(String alias) {
        aliases.add(new PersonAlias(sheetId, alias));
    }
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /**
     * A person as listed: the grade is the one in force on the sheet's today, the grades every one recorded, the
     * terms their own (null: none); clashing when their name or an alias is on another sheet of the sheet's tree.
     */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            LocalDate retiredFrom, boolean held, List<HoldView> holds, Integer terms, String contact,
            List<String> aliases, boolean clashing) {
        public static PersonView of(Person p, LocalDate today, Set<Long> clashing) {
            return new PersonView(p.getId(), p.getName(), p.gradeOn(today),
                    p.getGrades().stream().map(GradeView::of).toList(), p.getVersion(), p.getRetiredFrom(),
                    p.isHeld(), p.getHolds().stream().map(HoldView::of).toList(), p.getTerms(),
                    p.getContact(), p.getAliases(), clashing.contains(p.getId()));
        }
    }

    /** A hold on a person from its from-date to its to-date (null: with no end). */
    public record HoldView(LocalDate from, LocalDate to) {
        public static HoldView of(DatedHold h) {
            return new HoldView(h.getFrom(), h.getTo());
        }
    }

    /** A grade a person has from its from-date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(DatedGrade g) {
            return new GradeView(g.getGrade(), g.getFrom());
        }
    }

    /**
     * A person's fields as the form submits them; the name is stored without surrounding spaces, the terms are whole
     * days, 0 or more, or null for none; the contact is stored without surrounding spaces, lower-cased, blank or
     * null for none.
     */
    public record PersonForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, @Min(0) @Max(99999) Integer terms,
            @Size(max = 200) String contact) {
    }

    /**
     * An edit of a person: its fields, the date its grade applies from (missing: the sheet's today) and the version
     * of the person the editor loaded, their own terms (null: none) and their contact (blank or null: none).
     */
    public record PersonEdit(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate gradeFrom, @NotNull Long version,
            @Min(0) @Max(99999) Integer terms, @Size(max = 200) String contact) {
    }

